/* Night Marquee Theme - slides surface: fixed 1920x1080 slide geometry and projection type ramp. */
/* Shared brand identity - colour, type families, spacing, radius, elevation, motion - stays in colors_and_type.css. */
/* Generated by scripts/build-theme-surfaces.ts; regenerate with `bun run surfaces`. */

:root {
  --slide-w: 1920px;
  --slide-h: 1080px;
  --slide-aspect: 16 / 9;
  --slide-pad-edge: 104px;
  --slide-pad-block: 48px;
  --slide-columns: 12;
  --slide-gutter: 24px;
  --slide-rule: 1px;
  --slide-type-hero: 96px;
  --slide-type-heading: 60px;
  --slide-type-body: 34px;
  --slide-type-caption: 26px;
}
